// Calculate timestamp for 24 hours ago
const oneDayAgo = Math.floor((Date.now() - 86400000) / 1000);

// Get channel info from previous node
const channel = $input.item.json;

return {
  channelId: channel.id,
  channelName: channel.name || 'DM',
  oldest: oneDayAgo.toString(),
  limit: 100
};

// Format Slack message for Google Sheets
const message = $input.item.json;
const channelName = $node['Prepare Channel Query'].json.channelName;

// Convert Slack timestamp to readable date/time
const timestamp = parseFloat(message.ts) * 1000;
const date = new Date(timestamp);

const formattedDate = date.toLocaleDateString('en-US');
const formattedTime = date.toLocaleTimeString('en-US');

// Extract user (if available)
const user = message.user || message.bot_id || 'Unknown';

// Get text content
const text = message.text || '';

// Check if it's a thread reply
const isThreadReply = message.thread_ts && message.thread_ts !== message.ts;

// Get reactions if any
const reactions = message.reactions 
  ? message.reactions.map(r => `${r.name}:${r.count}`).join(', ')
  : '';

// Check for attachments/files
const hasAttachments = (message.files && message.files.length > 0) || 
                       (message.attachments && message.attachments.length > 0);
const attachmentInfo = hasAttachments ? 'Yes' : 'No';

return {
  date: formattedDate,
  time: formattedTime,
  channel: channelName,
  user: user,
  message: text,
  isThreadReply: isThreadReply ? 'Yes' : 'No',
  reactions: reactions,
  hasAttachments: attachmentInfo,
  permalink: message.permalink || ''
};
